# Code Capture interactions for the Mosaiq application.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_patient_code_summary() -> None:
    CommonActions.left_click_object(MosaiqCoreObjects.menuBar_Item_CodeMgmt)
    CommonActions.left_click_object(MosaiqCoreObjects.code_management_patient_code_summary)

# Close button interaction for the Code Capture summary window.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_close_button_code_summary() -> None:
    print("Clicking close button in Code Capture window")
    CommonActions.left_click_object(MosaiqCodeCaptureObjects.close_button)

# Verify the selected view in the Code Capture summary window. In this case verifying that 'By Patient' option is selected.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def verify_code_view_selection(expected_view: str = "By Patient") -> bool:
    """Verify that the Code Capture View field displays the expected selected view."""
    print("Verifying code view selection in Code Capture window")
    time.sleep(1)
    try:
        summary_window = CommonActions.wait_for_object_exists(MosaiqCodeCaptureObjects.code_capture_summary_window, 3000)
    except Exception as ex:
        raise RuntimeError(
            "Code Capture Summary window could not be resolved; refusing to verify View "
            f"against background windows: {ex!r}"
        )

    # Extract all text from the Code Capture Summary window using OCR.
    raw_text = CommonActions.get_all_text_via_ocr_in_object(summary_window) or ""
    normalized_text = " ".join(raw_text.split())
    #print(f"[Code Capture debug] view OCR text: {raw_text!r}")

    if "code capture summary" not in normalized_text.casefold():
        raise AssertionError(
            "OCR scope did not contain the Code Capture Summary title; View verification "
            f"may not be scoped to the summary window. Actual OCR text: {raw_text!r}"
        )

    if expected_view.casefold() not in normalized_text.casefold():
        raise AssertionError(
            f"Expected Code Capture View to be '{expected_view}', but it was not found. "
            f"Actual OCR text: {raw_text!r}"
        )

    print(f"Verified Code Capture View selection: {expected_view}")
    return True

# Verify the details in the Code Capture summary window. Update the details as needed based on the expected values for the selected patient.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)

def verify_code_capture_summary(
    expected_patient: str = "AndersonTRN, Ron",
    expected_date: str = "4/02/2010",
    #expected_description: str = "Dly Tx | 6-10MV/MeV",
    #expected_description: str = "Dly Tx I 6-10MV/MeV",
    expected_hosp_code: str = "77408",
    expected_icd_code: str = "154.1",
    expected_qty: str = "1"
) -> bool:
 
    print("Verifying code capture summary in Code Capture window")
    time.sleep(1)

    raw_text = CommonActions.get_all_text_via_ocr_in_object(MosaiqCodeCaptureObjects.dashboard_code_capture_window) or ""
    normalized_text = " ".join(raw_text.split())
    #print(f"[Code Capture debug] summary OCR text: {raw_text!r}")

    # Native grid headers are frequently merged or omitted by OCR. Validate stable headers directly and use the expected row values as evidence for headers that OCR drops.
    normalized_lower = normalized_text.casefold()
    header_checks = {
        "Date": "date" in normalized_lower,
        '''
        "Description": "description" in normalized_lower or (
            bool(expected_description) and expected_description.casefold() in normalized_lower
        ),
        '''

        "Hosp Code": "hosp code" in normalized_lower or "host code" in normalized_lower,
        "Qty": "qty" in normalized_lower or (
            bool(expected_qty) and re.search(rf"\b{re.escape(expected_qty)}\b", normalized_text) is not None
        ),
        "ICD Codes": "icd codes" in normalized_lower or (
            bool(expected_icd_code) and expected_icd_code.casefold() in normalized_lower
        ),
    }
    missing_headers = [header for header, present in header_checks.items() if not present]
    if missing_headers:
        raise AssertionError(
            f"Code Capture Summary is missing headers: {missing_headers}. "
            f"Actual OCR text: {raw_text!r}"
        )

    data_lines = [line.strip() for line in raw_text.splitlines() if line.strip()]
    date_pattern = re.compile(r"\d{1,2}/\d{1,2}/\d{2,4}")
    charge_rows = [line for line in data_lines if date_pattern.search(line)]
    if not charge_rows:
        raise AssertionError(f"No captured charge rows were displayed. Actual OCR text: {raw_text!r}")

    expected_values = {
        "Patient": expected_patient,
        "Date": expected_date,
        #"Description": expected_description,
        "Hosp Code": expected_hosp_code,
        "Qty": expected_qty,
        "ICD Codes": expected_icd_code
    }
    missing_values = {
        label: value
        for label, value in expected_values.items()
        if value and value.casefold() not in normalized_text.casefold()
    }
    if missing_values:
        raise AssertionError(
            f"Code Capture Summary is missing expected values: {missing_values}. "
            f"Actual OCR text: {raw_text!r}"
        )

    print(f"Verified Code Capture Summary with {len(charge_rows)} charge row(s): {charge_rows}")
    return True

# Select a charge in the Code Capture window.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_charge() -> None:
    print("Selecting charge in Code Capture window")
    CommonActions.press_key_spacebar()
    time.sleep(1)

# Extract the details of a tagged charge row from OCR text.
def _tagged_charge_row_details(raw_text: str) -> tuple[str, dict[str, str]]:
    lines = [line.strip() for line in raw_text.splitlines() if line.strip()]
    date_pattern = re.compile(r"\d{1,2}/\d{1,2}/\d{2,4}")

    for index, marker_line in enumerate(lines):
        if not re.search(r">>|\u00bb", marker_line):
            continue

        row_line = marker_line
        date_match = date_pattern.search(row_line)
        if date_match is None and index + 1 < len(lines):
            row_line = lines[index + 1]
            date_match = date_pattern.search(row_line)
        if date_match is None:
            continue

        details = {"Date": date_match.group(0)}
        trailing_values = row_line[date_match.end():].strip()
        if trailing_values:
            details["Row values"] = trailing_values
        return f"{marker_line} | {row_line}", details

    return "", {}

# Verify the tagged charge marker ">>" in the Code Capture Summary grid that the previously selected row remains selected after closing the Edit Tagged Charges window.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def verify_tagged_charge_marker(screenshot_path: str = "") -> bool:
    try:
        summary_grid = CommonActions.wait_for_object_exists(MosaiqCodeCaptureObjects.charge_summary_grid, 3000)
    except Exception as ex:
        raise RuntimeError(
            "Code Capture Summary grid could not be resolved; cannot verify the tagged-row "
            f"marker: {ex!r}"
        )

    raw_text = CommonActions.get_all_text_via_ocr_in_object(summary_grid) or ""
    #print(f"[Code Capture debug] tagged-grid OCR text: {raw_text!r}")
    marker_row, details = _tagged_charge_row_details(raw_text)
    if marker_row:
        print("Verified tagged charge marker in the Code Capture Summary grid")
        print(f"Tagged charge row OCR: {marker_row!r}")
        print(f"Tagged charge row details: {details}")
        return True

    screenshot_file = screenshot_path or os.path.join(os.getcwd(), "code_capture_tagged_grid.png")
    try:
        squishtest.grabWidget(summary_grid).save(screenshot_file, "PNG")
        diagnostic = f" Grid screenshot saved to: {screenshot_file}"
    except Exception as ex:
        diagnostic = f" Grid screenshot could not be saved: {ex!r}"
    raise AssertionError(
        "Tagged charge marker ('>>') was not recognized inside the Code Capture Summary grid."
        f" OCR text: {raw_text!r}.{diagnostic}"
    )

# Edit the tagged charges in the code capture window.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_edit_tagged_charges() -> None:
    print("Editing tagged charges in Code Capture window")
    CommonActions.press_key_sequence("<Ctrl+E>")
    time.sleep(1)

# Verify the Edit Tagged Charges window in the Code Capture window for certain expected items like Edit Diagnosis, Edit Facility, Edit POS Code, and Edit Admit.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def verify_edit_tagged_charges_window(expected_items: list[str]) -> None:
    print("Verifying Edit Tagged Charges window in Code Capture window")
    raw_text = CommonActions.get_all_text_via_ocr_in_object(MosaiqCodeCaptureObjects.charge_summary_grid)

    found_items = [item for item in expected_items if item in raw_text]
    missing_items = [item for item in expected_items if item not in raw_text]

    assert not missing_items, (
        f"Missing items: {missing_items}\n"
        f"Found items: {found_items}\n"
        f"Actual OCR text:\n{raw_text}"
    )
    print(f"Successfully verified {len(found_items)} items in Edit Tagged Charges window")

# Cancel the tagged charges in the Code Capture window.
deco.set_separate_app_context(MOSAIQ_APP_NAME)
def cancel_tagged_charges() -> None:
    print("Cancelling tagged charges in Code Capture window")
    CommonActions.press_key_sequence("<Alt+C>")
    time.sleep(1)

